package main

import "fmt"

type Account struct {
	Balance float64
}

func (a Account) DepositWrong(amount float64) {
	a.Balance += amount   // mutates a COPY -- caller's Account is untouched
}

func (a *Account) Deposit(amount float64) {
	a.Balance += amount   // mutates through the pointer -- reaches the real Account
}

func main() {
	acc := Account{Balance: 100}

	acc.DepositWrong(50)
	fmt.Println(acc.Balance)   // 100 -- unchanged

	acc.Deposit(50)
	fmt.Println(acc.Balance)   // 150 -- changed
}

