// file: bank/account.go
package bank

type Account struct {
	Owner   string   // exported
	balance float64   // unexported
}

func NewAccount(owner string, initial float64) *Account {
	return &Account{Owner: owner, balance: initial}
}

func (a *Account) Balance() float64 {   // exported method exposes the unexported field, in a controlled way
	return a.balance
}

// file: main.go
package main

import (
	"fmt"
	"example.com/app/bank"
)

func main() {
	acc := bank.NewAccount("Amy", 100)
	fmt.Println(acc.Owner)      // fine -- Owner is exported
	fmt.Println(acc.Balance())   // fine -- calling the exported method
	// fmt.Println(acc.balance)  // compile error: acc.balance undefined (cannot refer to unexported field)
}

package main

import (
	"fmt"
	"io"
	"strings"
)

func printAllUppercase(r io.Reader) {
	data, _ := io.ReadAll(r)
	fmt.Println(strings.ToUpper(string(data)))
}

func main() {
	printAllUppercase(strings.NewReader("hello from a string"))
	// The exact same function would also accept an *os.File, a bytes.Buffer,
	// an http.Response.Body, or anything else implementing io.Reader --
	// printAllUppercase never needed to know any of those types exist.
}

package main

import (
	"fmt"
	"io"
	"strings"
)

type WordCounter struct {
	Count int
}

func CountWords(r io.Reader) *WordCounter {   // accepts the loose, small interface
	data, _ := io.ReadAll(r)
	words := strings.Fields(string(data))
	return &WordCounter{Count: len(words)}   // returns the specific, rich concrete type
}

func main() {
	result := CountWords(strings.NewReader("the quick brown fox"))
	fmt.Println(result.Count)   // 4 -- full access to WordCounter's own fields, nothing hidden
}

